// Tamil numerology texts. Keys match numerologyTextsEn in numerology_texts.dart.
const numerologyTextsTa = <String, String>{
  // What each number type represents
  'type.lifePath': 'வாழ்க்கைப் பாதை எண் முழுப் பிறந்த தேதியிலிருந்து கணக்கிடப்படுகிறது. மரபுப்படி இது வாழ்நாள் முழுவதற்குமான மையக் கருப்பொருளாகக் கருதப்படுகிறது: மீண்டும் மீண்டும் வரும் பாடங்கள், ஆர்வங்கள், திசை.',
  'type.birthday': 'பிறந்தநாள் எண் மாதத்தின் பிறந்த தேதியை மட்டும் கொண்டு கணக்கிடப்படுகிறது. வாழ்க்கைப் பாதைக்கு நீங்கள் கொண்டுவரும் ஒரு தனித் திறமையாகவோ செயல்படும் விதமாகவோ இது கருதப்படுகிறது.',
  'type.mulank': 'மூல எண் (முலாங்க்) பிறந்த தேதியிலிருந்து (மாதத்தின் நாள்) கணக்கிடப்படுகிறது. இந்திய எண் கணிதம் இதை உங்கள் அடிப்படை இயல்பாகக் கருதுகிறது: நாள்தோறும் நீங்கள் எப்படிச் சிந்திக்கிறீர்கள், எப்படிச் செயல்படுகிறீர்கள் என்பது.',
  'type.bhagyank': 'விதி எண் (பாக்யாங்க்) பிறந்த தேதியின் எல்லா இலக்கங்களையும் கூட்டிக் கணக்கிடப்படுகிறது. இந்திய எண் கணிதம் இதை வாழ்க்கையின் பரந்த திசையாகவும், அதனுடன் வரும் வாய்ப்புகளின் தன்மையாகவும் கருதுகிறது.',
  'type.expression': 'வெளிப்பாட்டு எண் முழுப் பெயரின் ஒவ்வொரு எழுத்திலிருந்தும் கணக்கிடப்படுகிறது. உங்கள் இயல்பான திறமைகளாகவும், அவற்றை வேலையிலும் வாழ்க்கையிலும் நீங்கள் வெளிப்படுத்தும் விதமாகவும் இது கருதப்படுகிறது.',
  'type.soulUrge': 'ஆன்ம எண் பெயரிலுள்ள உயிரெழுத்துகளிலிருந்து கணக்கிடப்படுகிறது. இது உள்ளார்ந்த உந்துதலாகக் கருதப்படுகிறது: வெளியில் காட்டாவிட்டாலும் நீங்கள் ஆழமாக விரும்புவது.',
  'type.personality': 'ஆளுமை எண் பெயரிலுள்ள மெய்யெழுத்துகளிலிருந்து கணக்கிடப்படுகிறது. நீங்கள் ஏற்படுத்தும் முதல் தோற்றமாகவும், மற்றவர்கள் உங்களைப் பொதுவாக எப்படிப் பார்க்கிறார்கள் என்பதாகவும் இது கருதப்படுகிறது.',
  'type.chaldeanName': 'கல்தேய பெயர் எண், எழுத்துகளின் ஒலியை அடிப்படையாகக் கொண்ட பழைய எழுத்து அட்டவணையைப் பயன்படுத்துகிறது. நீங்கள் அறியப்படும் பெயரின் ஒட்டுமொத்த அதிர்வாக இது கருதப்படுகிறது.',

  // Fuller meanings: strengths, challenges, practical guidance
  'num.1.strengths': 'முன்முயற்சி, சுதந்திரம், புதியவற்றைத் தொடங்கி வழிநடத்தும் துணிவு.',
  'num.1.challenges': 'பொறுமையின்மை, பிடிவாதம் அல்லது உதவியை ஏற்கத் தயக்கம் ஏற்படலாம்.',
  'num.1.guidance': 'புதிய பணிகளில் முன்னின்று செயல்படுங்கள்; ஆனால் முடிவெடுக்கும் முன் மற்றவர்கள் சொல்வதைக் கேளுங்கள், பெருமையைப் பகிர்ந்துகொள்ளுங்கள்.',
  'num.2.strengths': 'சாதுர்யம், பொறுமை, மற்றவர்கள் மீதான உணர்திறன், ஒத்துழைக்கும் இயல்பான திறன்.',
  'num.2.challenges':
      'அதிக உணர்ச்சிவசப்படுதல், முடிவெடுக்கத் தயக்கம் அல்லது எல்லோரையும் மகிழ்விக்க அதிக ஆர்வம் இருக்கலாம்.',
  'num.2.guidance':
      'கூட்டாண்மையும் குழுப்பணியும் உங்களுக்கு ஏற்றவை; தேவைப்படும்போது அமைதியாக "இல்லை" என்று சொல்லப் பழகுங்கள்.',
  'num.3.strengths': 'படைப்பாற்றல், மகிழ்ச்சியான வெளிப்பாடு, பேச்சிலும் மக்களுடன் பழகுவதிலும் திறமை.',
  'num.3.challenges': 'பல ஆர்வங்களில் ஆற்றல் சிதறலாம்; வழக்கமான பணிகளைத் தவிர்க்கக்கூடும்.',
  'num.3.guidance':
      'முடிப்பதற்கு ஒன்றிரண்டு திட்டங்களைத் தேர்ந்தெடுங்கள்; மற்றவர்களை ஊக்குவிக்க உங்கள் குரலைப் பயன்படுத்துங்கள்.',
  'num.4.strengths': 'நம்பகத்தன்மை, ஒழுங்குமுறை, கடின உழைப்பு, நடைமுறையில் சிக்கல்களைத் தீர்க்கும் திறன்.',
  'num.4.challenges': 'நெகிழ்வின்மை, அதிக வேலைச்சுமை அல்லது திடீர் மாற்றங்களை எதிர்க்கும் போக்கு இருக்கலாம்.',
  'num.4.guidance': 'படிப்படியாகக் கட்டியெழுப்புங்கள், சிறிது நெகிழ்வுத்தன்மையை வைத்திருங்கள், வேலையைப் போலவே ஓய்வையும் தீவிரமாகத் திட்டமிடுங்கள்.',
  'num.5.strengths': 'ஆர்வம், சூழலுக்கு ஏற்ப மாறும் திறன், விரைவான சிந்தனை, தொடர்பாடல் திறன்.',
  'num.5.challenges': 'அமைதியின்மை, அவசர முடிவுகள், ஒரு பொறுப்பில் நிலைத்திருப்பதில் சிரமம்.',
  'num.5.guidance':
      'மாற்றத்தை வரவேற்றாலும் சில நிலையான பழக்கங்களைத் தொடருங்கள்; பெரிய இடர்களை எடுக்கும் முன் இருமுறை யோசியுங்கள்.',
  'num.6.strengths': 'அக்கறை, பொறுப்புணர்வு, அழகுணர்ச்சி, வீட்டில் இணக்கம்.',
  'num.6.challenges':
      'மற்றவர்களுக்காக அளவுக்கு மீறிச் சுமை ஏற்றல், கவலைப்படுதல் அல்லது கட்டுப்படுத்த முயலுதல் இருக்கலாம்.',
  'num.6.guidance':
      'உங்களைப் புறக்கணிக்காமல் மற்றவர்களுக்குச் சேவை செய்யுங்கள்; அவரவர் பிரச்சினைகளை அவர்களே தீர்க்க விடுங்கள்.',
  'num.7.strengths': 'ஆழ்ந்த சிந்தனை, ஆய்வு, உள்ளுணர்வு, வளமான அக வாழ்க்கை.',
  'num.7.challenges': 'தனக்குள் ஒதுங்குதல், அளவுக்கு மீறி யோசித்தல் அல்லது பிறரை நம்புவதில் சிரமம் இருக்கலாம்.',
  'num.7.guidance': 'படிப்புக்கும் அமைதிக்கும் நேரம் ஒதுக்குங்கள்; நம்பிக்கைக்குரிய சிலரிடம் உங்கள் எண்ணங்களைப் பகிர்ந்துகொள்ளுங்கள்.',
  'num.8.strengths': 'ஒழுக்கம், லட்சியம், பொறுமை, வளங்களை நிர்வகிக்கும் திறன்.',
  'num.8.challenges':
      'அளவுக்கு மீறிய கண்டிப்பு, வேலையிலேயே முழுக் கவனம் அல்லது பலன்கள் மெதுவாக வருவதாக உணர்தல் இருக்கலாம்.',
  'num.8.guidance': 'மரபுப்படி நிலையான முயற்சிக்குக் காலப்போக்கில் பலன் கிடைக்கும் எனக் கருதப்படுகிறது; வேலையையும் குடும்பம், உடல்நலத்தையும் சமநிலையில் வையுங்கள்.',
  'num.9.strengths': 'கருணை, தைரியம், தாராள மனம், பரந்த கண்ணோட்டம்.',
  'num.9.challenges':
      'பொறுமையின்மை, விரைவில் கோபப்படுதல் அல்லது களைத்துப்போகும் வரை கொடுத்துக்கொண்டே இருத்தல் இருக்கலாம்.',
  'num.9.guidance': 'நீங்கள் அக்கறை கொள்ளும் நோக்கங்களில் ஆற்றலைச் செலுத்துங்கள்; தொடங்கியதை முடியுங்கள், விட வேண்டியதை நயமாக விட்டுவிடுங்கள்.',
  'num.11.strengths': 'உள்ளுணர்வு, உத்வேகம், மற்றவர்களை உயர்த்தும் திறன்.',
  'num.11.challenges': 'நரம்புப் பதற்றம், சுய சந்தேகம், தன்மீது அதிக எதிர்பார்ப்பு.',
  'num.11.guidance': 'எண்ணங்களை அன்றாடப் பயிற்சியில் நிலைநிறுத்துங்கள்; சாதாரண நாட்களில் 2-இன் குணங்கள் பொருந்தும்.',
  'num.22.strengths': 'நீடித்து நிற்பவற்றை உருவாக்கும் நடைமுறைத் திறனுடன் இணைந்த தொலைநோக்கு.',
  'num.22.challenges': 'அதிகம் சாதிக்க வேண்டும் என்ற அழுத்தம்; பெரிய திட்டங்களால் திணறலாம்.',
  'num.22.guidance': 'பெரிய இலக்குகளைச் சிறு படிகளாகப் பிரியுங்கள்; சாதாரண நாட்களில் 4-இன் குணங்கள் பொருந்தும்.',
  'num.33.strengths': 'கருணையுடன் கற்பித்தல், குணப்படுத்துதல், பிறருக்குச் சேவை.',
  'num.33.challenges': 'சுய தியாகம், பிறரின் சுமைகளைச் சுமத்தல், எதிலும் முழுமையை எதிர்பார்த்தல்.',
  'num.33.guidance': 'மற்றவர்களைப் போலவே உங்களையும் கவனித்துக்கொள்ளுங்கள்; சாதாரண நாட்களில் 6-இன் குணங்கள் பொருந்தும்.',

  // Mulank-Bhagyank pair
  'pair.intro': 'மூல எண் நாள்தோறும் நீங்கள் செயல்படும் விதத்தைக் காட்டுகிறது; விதி எண் வாழ்க்கையின் பரந்த திசையைக் காட்டுகிறது. இந்திய எண் கணிதம் இவற்றின் அதிபதி கிரகங்களை, கிரகங்களின் பாரம்பரிய இயற்கை நட்பு முறையின்படி ஒப்பிடுகிறது.',
  'pair.same': 'இரண்டு எண்களுக்கும் ஒரே கிரகம் அதிபதி; எனவே மரபுப்படி அதன் குணங்கள் வலுப்பெறுவதாகக் கருதப்படுகிறது: அதன் பலங்களும் கூடுகின்றன, அதன் வழக்கமான சவால்களும் கூடுகின்றன.',
  'pair.friendly': 'அதிபதி கிரகங்கள் இயற்கை நண்பர்கள்; எனவே மரபுப்படி உங்கள் இயல்பும் (மூல எண்) வாழ்க்கைத் திசையும் (விதி எண்) ஒன்றுக்கொன்று துணைபுரிவதாகக் கருதப்படுகிறது.',
  'pair.neutral': 'கிரகங்கள் ஒன்றுக்கொன்று சமமானவை, அல்லது ஒன்றையொன்று வெவ்வேறு விதமாகப் பார்க்கின்றன; எனவே மரபுப்படி இந்த இணை செயல்படக்கூடியதாகக் கருதப்படுகிறது: இரு தாக்கங்களும் ஒன்றுக்கொன்று பெரிதாக உதவுவதுமில்லை, தடுப்பதுமில்லை.',
  'pair.challenging': 'பாரம்பரிய அட்டவணையில் இந்தக் கிரகங்கள் இயற்கைப் பகைவர்கள்; எனவே மரபுப்படி இயல்புக்கும் வாழ்க்கைத் திசைக்கும் இடையே சிறிது உள் முரண்பாடு இருக்கலாம் எனக் கருதப்படுகிறது. இது கெட்ட அறிகுறியாக அல்ல, விழிப்புடன் சமநிலைப்படுத்த வேண்டிய ஒன்றாகவே கருதப்படுகிறது.',
  'pair.nodesNote': 'ராகு (4), கேது (7) ஆகியவை பாரம்பரிய நட்பு அட்டவணையில் இல்லை. இந்தச் செயலி பிற்காலத்தில் பரவலாகப் பின்பற்றப்படும் ஒரு வழக்கத்தைப் பயன்படுத்துகிறது (ராகுவுக்கு நண்பர்கள்: புதன், சுக்கிரன், சனி; கேதுவுக்கு நண்பர்கள்: செவ்வாய், சுக்கிரன், சனி); மரபுகளுக்கிடையே இதில் கருத்து வேறுபாடு உண்டு.',

  // Lo Shu grid
  'loshu.intro': 'லோ ஷு சதுரம் ஒரு பழமையான சீன மாயச் சதுரம்; இதில் ஒவ்வொரு வரிசை, நெடுவரிசை, மூலைவிட்டத்தின் கூட்டுத்தொகையும் 15. பிறந்த தேதியின் ஒவ்வொரு இலக்கமும் அதற்குரிய அறையில் வைக்கப்படுகிறது (அமைப்பு 4-9-2 / 3-5-7 / 8-1-6); பூஜ்ஜியங்கள் கணக்கில் கொள்ளப்படுவதில்லை.',
  'loshu.indianNote': 'வழக்கமான இந்திய முறையில் விதி எண்ணும் சேர்க்கப்படுகிறது; பிறந்த தேதி 1-9, 10, 20 அல்லது 30 ஆக இல்லாவிட்டால் மூல எண்ணும் சேர்க்கப்படுகிறது (அந்தத் தேதிகளில் அது ஏற்கெனவே கட்டத்தில் இருக்கும்). தேதியின் கட்டத்தை மட்டும் காண இதை அணைத்துவிடுங்கள்.',
  'loshu.missing.1': '1 இல்லை: உங்களையும் உங்கள் உணர்வுகளையும் வெளிப்படுத்துவதற்குக் கவனமான முயற்சி தேவைப்படலாம்.',
  'loshu.missing.2': '2 இல்லை: பொறுமையையும் மற்றவர்கள் மீதான உணர்திறனையும் வளர்த்துக்கொள்ள வேண்டியிருக்கலாம்.',
  'loshu.missing.3': '3 இல்லை: கற்பனைத் திறனுக்கும் உங்கள் எண்ணங்கள் மீதான நம்பிக்கைக்கும் ஊக்கம் தேவைப்படலாம்.',
  'loshu.missing.4': '4 இல்லை: ஒழுங்கு, கட்டுப்பாடு, அன்றாட முறைமை ஆகியவற்றில் தனிக் கவனம் செலுத்த வேண்டியிருக்கலாம்.',
  'loshu.missing.5': '5 இல்லை: உணர்ச்சிச் சமநிலைக்கும் நிலையான கவனத்துக்கும் பயிற்சி தேவைப்படலாம்.',
  'loshu.missing.6': '6 இல்லை: வீடு, குடும்பப் பொறுப்புகள், சௌகரியம் ஆகியவற்றில் கூடுதல் அக்கறை தேவைப்படலாம்.',
  'loshu.missing.7':
      '7 இல்லை: பாடங்கள் பெரும்பாலும் அனுபவத்தின் மூலமே வருகின்றன; சிந்தித்துப் பார்க்க நேரம் ஒதுக்குவது உதவும்.',
  'loshu.missing.8': '8 இல்லை: சிறு விவரங்களில் கவனம் செலுத்தவும் பணத்தைக் கவனமாக நிர்வகிக்கவும் முயற்சி தேவைப்படலாம்.',
  'loshu.missing.9': '9 இல்லை: லட்சியத்தையும் பரந்த நோக்கத்தையும் திட்டமிட்டு வளர்த்துக்கொள்ள வேண்டியிருக்கலாம்.',
  'loshu.repeat.1.2': '1 இரண்டு முறை: மரபுப்படி சமநிலையான, தெளிவான சுய வெளிப்பாடாகக் கருதப்படுகிறது.',
  'loshu.repeat.1.3': '1 மூன்று அல்லது அதற்கு மேல்: அதிகம் பேசக்கூடும், அல்லது ஆழ்ந்த உணர்வுகளைச் சொற்களில் வெளிப்படுத்துவது கடினமாக இருக்கலாம்.',
  'loshu.repeat.2.2': '2 இரண்டு முறை: வலுவான உள்ளுணர்வும் உணர்திறனும்; மனிதர்களைச் சரியாக எடைபோடும் திறன்.',
  'loshu.repeat.2.3':
      '2 மூன்று அல்லது அதற்கு மேல்: எளிதில் மனம் புண்படலாம்; உங்கள் உணர்ச்சி ஆற்றலைப் பாதுகாத்துக்கொள்வது உதவும்.',
  'loshu.repeat.3.2': '3 இரண்டு முறை: வளமான கற்பனையும் படைப்பாற்றல் மிக்க, சுறுசுறுப்பான மனமும்.',
  'loshu.repeat.3.3':
      '3 மூன்று அல்லது அதற்கு மேல்: எண்ணங்கள் சிதறலாம் அல்லது கவலையாக மாறலாம்; விஷயங்களை எழுதி வைப்பது உதவும்.',
  'loshu.repeat.4.2': '4 இரண்டு முறை: மிகுந்த ஒழுங்கும் கடின உழைப்பும்; நடைமுறைத் திறன்களில் சிறப்பு.',
  'loshu.repeat.4.3':
      '4 மூன்று அல்லது அதற்கு மேல்: நெகிழ்வின்மை அல்லது பொருள் சார்ந்த விஷயங்களில் அதிகக் கவனம் ஏற்படலாம்.',
  'loshu.repeat.5.2': '5 இரண்டு முறை: வலுவான உந்துதலும் மன உறுதியும்.',
  'loshu.repeat.5.3': '5 மூன்று அல்லது அதற்கு மேல்: அவசரத்தில் செயல்படவோ பேசவோ கூடும்; எதிர்வினையாற்றும் முன் சற்று நிதானிப்பது உதவும்.',
  'loshu.repeat.6.2': '6 இரண்டு முறை: வீடு, குடும்பம் மீது ஆழ்ந்த அக்கறை.',
  'loshu.repeat.6.3': '6 மூன்று அல்லது அதற்கு மேல்: அன்புக்குரியவர்களைப் பற்றிக் கவலைப்படலாம் அல்லது அளவுக்கு மீறிப் பாதுகாக்க முயலலாம்.',
  'loshu.repeat.7.2':
      '7 இரண்டு முறை: அனுபவத்திலிருந்து ஆழமாகக் கற்றுக்கொள்ளும் இயல்பு; படிப்பிலும் அகக் கேள்விகளிலும் ஈர்ப்பு.',
  'loshu.repeat.7.3': '7 மூன்று அல்லது அதற்கு மேல்: வாழ்க்கைப் பாடங்கள் சில நேரங்களில் கனமாகத் தோன்றலாம்; ஓய்வும் பிறரின் ஆதரவும் முக்கியம்.',
  'loshu.repeat.8.2': '8 இரண்டு முறை: முறையான அணுகுமுறை, நுணுக்கங்களில் கவனம், நம்பகத்தன்மை.',
  'loshu.repeat.8.3':
      '8 மூன்று அல்லது அதற்கு மேல்: அமைதியின்மை அல்லது எதிலும் முழுமையை எதிர்பார்க்கும் போக்கு ஏற்படலாம்.',
  'loshu.repeat.9.2': '9 இரண்டு முறை: இலட்சியவாத மனப்பான்மை, முன்னேற வேண்டும் என்ற ஆர்வம், விரைவான புரிதல்.',
  'loshu.repeat.9.3': '9 மூன்று அல்லது அதற்கு மேல்: மற்றவர்களிடம் விமர்சனப் போக்கோ பொறுமையின்மையோ ஏற்படலாம்.',
  'loshu.plane.mental.name': 'மனத் தளம்',
  'loshu.plane.mental.meaning':
      'மேல் வரிசை முழுமையாக உள்ளது: மரபுப்படி நல்ல நினைவாற்றல், பகுப்பாய்வு, திட்டமிடலுடன் தொடர்புடையது.',
  'loshu.plane.emotional.name': 'உணர்ச்சித் தளம்',
  'loshu.plane.emotional.meaning': 'நடு வரிசை முழுமையாக உள்ளது: மரபுப்படி உணர்வின் ஆழத்துடனும் பிறர் உணர்வைப் புரிந்துகொள்ளும் தன்மையுடனும் தொடர்புடையது.',
  'loshu.plane.practical.name': 'நடைமுறைத் தளம்',
  'loshu.plane.practical.meaning':
      'கீழ் வரிசை முழுமையாக உள்ளது: மரபுப்படி நடைமுறைத் திறனுடனும் காரியங்களைச் செய்து முடிப்பதுடனும் தொடர்புடையது.',
  'loshu.plane.thought.name': 'சிந்தனைத் தளம்',
  'loshu.plane.thought.meaning':
      'இடது நெடுவரிசை முழுமையாக உள்ளது: மரபுப்படி யோசனைகள், திட்டமிடல், ஒழுங்கமைத்தலுடன் தொடர்புடையது.',
  'loshu.plane.will.name': 'மன உறுதித் தளம்',
  'loshu.plane.will.meaning': 'நடு நெடுவரிசை முழுமையாக உள்ளது: மரபுப்படி மன உறுதி, விடாமுயற்சியுடன் தொடர்புடையது.',
  'loshu.plane.action.name': 'செயல் தளம்',
  'loshu.plane.action.meaning':
      'வலது நெடுவரிசை முழுமையாக உள்ளது: மரபுப்படி யோசனைகளைச் செயலாக மாற்றுவதுடன் தொடர்புடையது.',
  'loshu.plane.golden.name': 'தங்கத் தளம்',
  'loshu.plane.golden.meaning': 'மூலைவிட்டம் 4-5-6 முழுமையாக உள்ளது: சில இந்திய எண் கணித நிபுணர்கள் இதை "தங்க யோகம்" என்று அழைத்து, நிலையான முயற்சி முன்னேற்றமாக மாறுவதாகக் கருதுகின்றனர்.',
  'loshu.plane.silver.name': 'வெள்ளித் தளம்',
  'loshu.plane.silver.meaning': 'மூலைவிட்டம் 2-5-8 முழுமையாக உள்ளது: சில இந்திய எண் கணித நிபுணர்கள் இதை "வெள்ளி யோகம்" என்று அழைத்து, உள்ளுணர்வுடனும் சொத்து தொடர்பான விஷயங்களுடனும் இணைக்கின்றனர்.',

  // Chaldean compound numbers (Cheiro's tradition, in neutral words)
  'compound.intro': 'கீரோவின் மரபில், சுருக்குவதற்கு முந்தைய கல்தேய கூட்டுத்தொகைக்கு (10-52) தனிப் பொருள் உண்டு; அது ஒற்றை இலக்க எண்ணுடன் சேர்த்துப் படிக்கப்படுகிறது.',
  'compound.10': '"அதிர்ஷ்டச் சக்கரம்" என்று அழைக்கப்படுகிறது: மரியாதை, தன்னம்பிக்கை, மாறி மாறி வரும் ஏற்ற இறக்கங்கள்; பரவலாக அறியப்படும் பெயர்.',
  'compound.11': 'மறைந்திருக்கும் தடைகள் குறித்தும், யாரை நம்புகிறீர்கள் என்பதிலும் கவனமாக இருக்க மரபு அறிவுறுத்துகிறது; நம்பிக்கையும் பொறுமையும் வலியுறுத்தப்படுகின்றன.',
  'compound.12': 'பிறருக்காகச் செய்யும் தியாகத்துடன் தொடர்புடையது; மக்களுக்கு உதவும்போதும் உங்கள் சொந்த நலன்களைக் காத்துக்கொள்ள மரபு அறிவுறுத்துகிறது.',
  'compound.13': 'மாற்றம், உருமாற்றம், முடிவுகளுக்குப் பின் வரும் புதிய தொடக்கங்களுடன் தொடர்புடையது; விவேகத்துடன் பயன்படுத்த வேண்டிய ஆற்றல்.',
  'compound.14': 'இயக்கம், வணிகம், மக்களுடனான தொடர்புகள்; ஊக முதலீட்டிலும் பிறரின் முடிவுகளைச் சார்ந்திருப்பதிலும் எச்சரிக்கையாக இருக்க மரபு அறிவுறுத்துகிறது.',
  'compound.15': 'வசீகரம், சொல்வன்மை, கலைத் திறமைகள்; பிறரிடமிருந்து உதவி கிடைக்கும். இவற்றை நேர்மையாகப் பயன்படுத்துமாறு மரபு கேட்டுக்கொள்கிறது.',
  'compound.16': 'திட்டங்களிலோ நிலையிலோ ஏற்படும் திடீர் மாற்றங்களுடன் தொடர்புடையது; கவனமான திட்டமிடலையும் பணிவையும் மரபு அறிவுறுத்துகிறது.',
  'compound.17': '"ஞானியரின் நட்சத்திரம்" என்று அழைக்கப்படுகிறது: அமைதி, அன்பு, சோதனைகளைக் கடந்து உயர்தல்; நினைவில் நிற்கும் பெயர்.',
  'compound.18': 'பொருள்சார் நோக்கங்களுக்கும் ஆன்மீக நோக்கங்களுக்கும் இடையிலான இழுபறியுடன் தொடர்புடையது; தகராறுகளில் கவனமாக இருக்க மரபு அறிவுறுத்துகிறது.',
  'compound.19':
      '"விண்ணுலக இளவரசன்" என்று அழைக்கப்படுகிறது: மகிழ்ச்சி, மதிப்பு, வெற்றி; மிகவும் சாதகமான எண்களில் ஒன்று.',
  'compound.20': '"விழிப்பு" என்று அழைக்கப்படுகிறது: புதிய நோக்கத்துக்கும் திட்டங்களுக்குமான அழைப்பு; பொருள் லாபத்தை விட அக வளர்ச்சியாகவே அதிகம் கருதப்படுகிறது.',
  'compound.21':
      '"ஞானியரின் மகுடம்" என்று அழைக்கப்படுகிறது: முன்னேற்றமும் அங்கீகாரமும், பெரும்பாலும் நீண்ட முயற்சிக்குப் பிறகு.',
  'compound.22': 'மாயைகள், அளவுக்கு மீறிய நம்பிக்கை, பிறரின் தவறான ஆலோசனை ஆகியவற்றில் கவனமாக இருக்க மரபு அறிவுறுத்துகிறது; உங்கள் சொந்த முடிவில் உறுதியாக இருங்கள்.',
  'compound.23': '"சிம்மத்தின் அரச நட்சத்திரம்" என்று அழைக்கப்படுகிறது: திட்டங்களில் வெற்றியும் அதிகாரத்தில் உள்ளவர்களின் உதவியும்.',
  'compound.24': 'சாதகமானது: உயர் பதவியில் உள்ளவர்களின் உதவி, காதலிலும் இணையுறவிலும் கனிவு.',
  'compound.25': 'அனுபவத்தாலும் கூர்ந்த கவனிப்பாலும் பெறும் வலிமை; தொடக்கத்தில் சோதனைகள், பின்னர் நிலைத்தன்மை.',
  'compound.26': 'கூட்டாண்மைகள், ஊக முதலீடு, பிறரின் ஆலோசனை ஆகியவற்றில் கவனமாக இருக்க மரபு அறிவுறுத்துகிறது; ஒப்பந்தங்களைத் தெளிவாக வைத்திருங்கள்.',
  'compound.27':
      '"செங்கோல்" என்று அழைக்கப்படுகிறது: உங்கள் சொந்தச் சிந்தனையாலும் படைப்புப் பணியாலும் அதிகாரமும் பலனும்.',
  'compound.28': 'நல்ல வாய்ப்புகளும் முன்னேற்றமும் தவறான இடத்தில் வைக்கும் நம்பிக்கையால் இழக்கப்படலாம்; கவனமான ஒப்பந்தங்களையும் எதிர்காலத்துக்கான சேமிப்பையும் மரபு அறிவுறுத்துகிறது.',
  'compound.29':
      'நெருங்கிய உறவுகளிலும், யாரைச் சார்ந்திருப்பது என்பதைத் தேர்ந்தெடுப்பதிலும் கவனமாக இருக்க மரபு அறிவுறுத்துகிறது.',
  'compound.30':
      'ஆழ்ந்த சிந்தனையும் மன வலிமையும்; அதிர்ஷ்டமானதும் அல்ல, அதிர்ஷ்டமற்றதும் அல்ல, கண்ணோட்டத்தைப் பொறுத்தது.',
  'compound.31': '30-ஐப் போன்றது, ஆனால் தன்னிறைவு அதிகம்; தனிமையை விரும்பக்கூடிய சிந்தனையாளர்.',
  'compound.32': 'மக்களை ஒன்றிணைத்தல், பிறரை இணங்கவைக்கும் திறனுடன் தொடர்புடையது; உங்கள் சொந்த முடிவில் உறுதியாக இருக்கும்போது சாதகமானது.',
  'compound.33': 'கீரோ இதை 24-ஐப் போலவே பொருள்கொள்கிறார்: உயர் பதவியில் உள்ளவர்களின் உதவி, உறவுகளில் கனிவு.',
  'compound.34':
      'கீரோ இதை 25-ஐப் போலவே பொருள்கொள்கிறார்: அனுபவத்தால் பெறும் வலிமை; தொடக்கத்தில் சோதனைகள், பின்னர் நிலைத்தன்மை.',
  'compound.35':
      'கீரோ இதை 26-ஐப் போலவே பொருள்கொள்கிறார்: கூட்டாண்மைகளிலும் ஊக முதலீட்டிலும் கவனமாக இருக்க மரபு அறிவுறுத்துகிறது.',
  'compound.36': 'கீரோ இதை 27-ஐப் போலவே பொருள்கொள்கிறார்: உங்கள் சொந்தச் சிந்தனையாலும் உழைப்பாலும் அதிகாரமும் பலனும்.',
  'compound.37': 'நட்பு, காதல், கூட்டாண்மைக்குச் சாதகமானது; இணக்கமான உறவுகள்.',
  'compound.38': 'கீரோ இதை 29-ஐப் போலவே பொருள்கொள்கிறார்: யாரைச் சார்ந்திருப்பது என்பதைத் தேர்ந்தெடுப்பதில் கவனமாக இருக்க மரபு அறிவுறுத்துகிறது.',
  'compound.39': 'கீரோ இதை 30-ஐப் போலவே பொருள்கொள்கிறார்: ஆழ்ந்த சிந்தனை; கண்ணோட்டத்தைப் பொறுத்தது.',
  'compound.40': 'கீரோ இதை 31-ஐப் போலவே பொருள்கொள்கிறார்: தன்னிறைவு, ஆழ்ந்த சிந்தனை, தனிமையை விரும்பக்கூடும்.',
  'compound.41': 'கீரோ இதை 32-ஐப் போலவே பொருள்கொள்கிறார்: மக்களை ஒன்றிணைத்தல்; சுயமாக முடிவெடுக்கும்போது சாதகமானது.',
  'compound.42': 'கீரோ இதை 24-ஐப் போலவே பொருள்கொள்கிறார்: உயர் பதவியில் உள்ளவர்களின் உதவி, உறவுகளில் கனிவு.',
  'compound.43': 'கொந்தளிப்பு, எதிர்ப்புடன் தொடர்புடையது; பொறுமை, நெகிழ்வுத்தன்மை, தேவையற்ற மோதல்களைத் தவிர்த்தல் ஆகியவற்றை மரபு அறிவுறுத்துகிறது.',
  'compound.44':
      'கீரோ இதை 26-ஐப் போலவே பொருள்கொள்கிறார்: கூட்டாண்மைகளிலும் ஊக முதலீட்டிலும் கவனமாக இருக்க மரபு அறிவுறுத்துகிறது.',
  'compound.45': 'கீரோ இதை 27-ஐப் போலவே பொருள்கொள்கிறார்: உங்கள் சொந்தச் சிந்தனையாலும் உழைப்பாலும் அதிகாரமும் பலனும்.',
  'compound.46': 'கீரோ இதை 37-ஐப் போலவே பொருள்கொள்கிறார்: நட்பு, காதல், கூட்டாண்மைக்குச் சாதகமானது.',
  'compound.47': 'கீரோ இதை 29-ஐப் போலவே பொருள்கொள்கிறார்: யாரைச் சார்ந்திருப்பது என்பதைத் தேர்ந்தெடுப்பதில் கவனமாக இருக்க மரபு அறிவுறுத்துகிறது.',
  'compound.48': 'கீரோ இதை 30-ஐப் போலவே பொருள்கொள்கிறார்: ஆழ்ந்த சிந்தனை; கண்ணோட்டத்தைப் பொறுத்தது.',
  'compound.49': 'கீரோ இதை 31-ஐப் போலவே பொருள்கொள்கிறார்: தன்னிறைவு, ஆழ்ந்த சிந்தனை, தனிமையை விரும்பக்கூடும்.',
  'compound.50': 'கீரோ இதை 32-ஐப் போலவே பொருள்கொள்கிறார்: மக்களை ஒன்றிணைத்தல்; சுயமாக முடிவெடுக்கும்போது சாதகமானது.',
  'compound.51': 'துணிச்சலான செயலுடனும் திடீர் முன்னேற்றத்துடனும் தொடர்புடையது; போட்டியாளர்கள் குறித்து விழிப்புடன் இருந்து கவனமாகச் செயல்பட மரபு அறிவுறுத்துகிறது.',
  'compound.52': 'கீரோ இதை 43-ஐப் போலவே பொருள்கொள்கிறார்: கொந்தளிப்பான காலங்களில் பொறுமையையும் நெகிழ்வுத்தன்மையையும் மரபு அறிவுறுத்துகிறது.',

  // Personal year / month / day
  'cycle.year': 'தனிப்பட்ட ஆண்டு = பிறந்த தேதி + பிறந்த மாதம் + நடப்பு ஆண்டு, ஒற்றை இலக்கமாகச் சுருக்கப்பட்டது. ஒன்பது ஆண்டுச் சுழற்சிக்குள், அந்த நாட்காட்டி ஆண்டுக்கான உங்கள் கருப்பொருளாக இது கருதப்படுகிறது.',
  'cycle.month':
      'தனிப்பட்ட மாதம் = தனிப்பட்ட ஆண்டு + நாட்காட்டி மாதம், சுருக்கப்பட்டது. ஆண்டுக்குள் ஒரு குறுகிய கருப்பொருள்.',
  'cycle.day': 'தனிப்பட்ட நாள் = தனிப்பட்ட மாதம் + நாட்காட்டித் தேதி, சுருக்கப்பட்டது. ஒரு நாளின் தொனி.',
  'cycle.1': 'புதிய தொடக்கங்கள்: திட்டங்களைத் தொடங்குங்கள், முன்முயற்சி எடுங்கள், விதை விதையுங்கள்.',
  'cycle.2': 'பொறுமையும் ஒத்துழைப்பும்: உறவுகள், மெதுவான முன்னேற்றம், பிறர் சொல்வதைக் கேட்டல்.',
  'cycle.3': 'வெளிப்பாடு: படைப்பாற்றல், சமூக வாழ்க்கை, தொடர்பாடல், மகிழ்ச்சி.',
  'cycle.4': 'அடித்தளம்: நிலையான உழைப்பு, ஒழுங்கமைத்தல், உடல்நல வழக்கங்கள்.',
  'cycle.5': 'மாற்றம்: பயணம், பல்வகைமை, சுதந்திரம்; சூழலுக்கு ஏற்ப மாறத் தயாராக இருங்கள்.',
  'cycle.6': 'வீடும் பொறுப்பும்: குடும்பம், அக்கறை, கடமைகள்.',
  'cycle.7': 'ஆழ்ந்த சிந்தனை: படிப்பு, ஓய்வு, சுயபரிசோதனை, மறுஆய்வு.',
  'cycle.8': 'முயற்சியும் பலனும்: தொழில், நிதி, நடைமுறை முடிவுகள்.',
  'cycle.9': 'நிறைவு: முடித்தல், விட்டுவிடுதல், தாராள மனம்; அடுத்து வருவதற்கு இடம் அளித்தல்.',

  // About the methods
  'about.pythagorean': 'பித்தாகரஸ் முறை (மேற்கத்திய): A-Z எழுத்துகள் வரிசையாக 1-9 மதிப்புகளைப் பெறுகின்றன (A=1 ... I=9, J=1 ...). இது வாழ்க்கைப் பாதை, வெளிப்பாட்டு, ஆன்ம, ஆளுமை எண்களைத் தருகிறது; முதன்மை எண்கள் 11, 22, 33 சுருக்கப்படாமல் அப்படியே வைக்கப்படுகின்றன.',
  'about.chaldean': 'கல்தேய முறை: எழுத்துகளுக்கு அவற்றின் ஒலியின் அடிப்படையில் 1-8 மதிப்புகளைத் தரும் பழைய முறை (9 புனிதமாகக் கருதப்படுவதால் எந்த எழுத்துக்கும் தரப்படுவதில்லை). சுருக்குவதற்கு முந்தைய கூட்டுத்தொகை கீரோவின் மரபில் கூட்டு எண்ணாகப் படிக்கப்படுகிறது.',
  'about.indian': 'இந்திய எண் கணிதம்: மூல எண் (பிறந்த தேதி), விதி எண் (முழுத் தேதி) ஒவ்வொன்றும் ஒரு கிரகத்துடன் இணைக்கப்பட்டுள்ளது: 1 சூரியன், 2 சந்திரன், 3 குரு, 4 ராகு, 5 புதன், 6 சுக்கிரன், 7 கேது, 8 சனி, 9 செவ்வாய். இவை எப்போதும் 1-9 ஆகச் சுருக்கப்படுகின்றன.',
  'about.loshu': 'லோ ஷு: பழமையான சீன 3×3 மாயச் சதுரம். எந்த எண்கள் வலுவாக உள்ளன, மீண்டும் வருகின்றன அல்லது இல்லை என்பதைக் காண பிறந்த தேதியின் இலக்கங்கள் இதில் வைக்கப்படுகின்றன; இந்திய எண் கணித நிபுணர்கள் பொதுவாக மூல எண்ணையும் விதி எண்ணையும் சேர்க்கின்றனர்.',
  'about.honest': 'எண் கணிதம் ஒரு மரபு சார்ந்த, குறியீட்டு முறை. எண்கள் நிகழ்வுகளையோ குணத்தையோ முன்கூட்டியே கணிக்கின்றன என்பதற்கு அறிவியல் சான்று எதுவும் இல்லை. இதைச் சுயசிந்தனைக்கான ஒரு தூண்டுதலாகப் படியுங்கள்; எந்த எண்ணையும் விட உங்கள் தேர்வுகளும் முயற்சிகளுமே முக்கியம்.',
};
